INSERT INTO `srm_project` (`id`, `project_no`, `project_name`, `project_date`, `dept_id`, `dept_name`, `project_desc`, `analysis_param_json`, `supplier_count`, `analysis_status`, `last_task_id`, `last_report_version_id`, `status`, `del_flag`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (1001, 'PRJ-2026-001', '华晟控股集团股权穿透专项分析', '2026-10-08', 100, '若依科技', '围绕华晟控股集团及其成员单位开展向上/向下穿透，识别最终受益人、疑似实际控制人及历史股东。', '{"direction":"both","upDepth":5,"downDepth":5,"minWeight":1,"relScope":"ALL","includeBookkeeping":"1","ruleVersionNo":1}', 8, '已完成', 1201, 1001, '0', '0', 'admin', '2026-10-08 09:00:00', 'admin', '2026-11-21 09:10:00', '演示项目：股权穿透 + 实际控制人识别');
INSERT INTO `srm_project` (`id`, `project_no`, `project_name`, `project_date`, `dept_id`, `dept_name`, `project_desc`, `analysis_param_json`, `supplier_count`, `analysis_status`, `last_task_id`, `last_report_version_id`, `status`, `del_flag`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (1002, 'PRJ-2026-002', '恒信供应链关联方风险排查', '2026-10-20', 100, '若依科技', '对恒信供应链及其关联方开展幕后关系排查，重点核对同电话、同邮箱、同注册地址与共同董监高。', '{"direction":"both","upDepth":4,"downDepth":4,"minWeight":3,"relScope":"ALL","includeBookkeeping":"1","ruleVersionNo":1}', 5, '已完成', 1202, 1002, '0', '0', 'admin', '2026-10-20 09:30:00', 'admin', '2026-11-21 14:20:00', '演示项目：幕后关系 + 账簿共用信息');
INSERT INTO `srm_project` (`id`, `project_no`, `project_name`, `project_date`, `dept_id`, `dept_name`, `project_desc`, `analysis_param_json`, `supplier_count`, `analysis_status`, `last_task_id`, `last_report_version_id`, `status`, `del_flag`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (1003, 'PRJ-2026-003', '2026 年度重点供应商监控名单核查', '2026-11-05', 100, '若依科技', '对全部在库重点供应商做全量关联复核，输出报告版本并在复核台完成线索结论确认。', '{"direction":"both","upDepth":6,"downDepth":6,"minWeight":1,"relScope":"ALL","includeBookkeeping":"1","ruleVersionNo":1}', 12, '已失败', 1203, 1003, '0', '0', 'admin', '2026-11-05 08:00:00', 'admin', '2026-11-22 08:40:00', '演示项目：全量复核 + 报告版本');
INSERT INTO `srm_project` (`id`, `project_no`, `project_name`, `project_date`, `dept_id`, `dept_name`, `project_desc`, `analysis_param_json`, `supplier_count`, `analysis_status`, `last_task_id`, `last_report_version_id`, `status`, `del_flag`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (1004, 'PRJ-2026-004', '2026 年度新增供应商准入关联核查', '2026-11-12', 100, '若依科技', '对华晟系、瑞昇系及新增准入供应商共 15 家开展准入前关联关系核查，覆盖股权穿透、幕后关系与账簿共用线索。', '{"direction":"both","upDepth":5,"downDepth":5,"minWeight":1,"relScope":"ALL","includeBookkeeping":"1","ruleVersionNo":1}', 15, '已完成', 1501, 1004, '0', '0', 'admin', '2026-11-12 09:00:00', 'admin', '2026-11-22 10:15:00', '演示项目：15 家供应商准入关联核查（本地库直接回放）');
INSERT INTO `srm_project` (`id`, `project_no`, `project_name`, `project_date`, `dept_id`, `dept_name`, `project_desc`, `analysis_param_json`, `supplier_count`, `analysis_status`, `last_task_id`, `last_report_version_id`, `status`, `del_flag`, `create_by`, `create_time`, `update_by`, `update_time`, `remark`) VALUES (1005, 'PRJ-2026-005', '重点供应商股权穿透复核（第二批）', '2026-11-18', 100, '若依科技', '对第二批 5 家重点供应商复核向上股东、向下投资与实际控制人链路，核对既有本地沉淀图谱是否仍然成立。', '{"direction":"both","upDepth":6,"downDepth":6,"minWeight":3,"relScope":"ALL","includeBookkeeping":"1","ruleVersionNo":1}', 5, '已完成', 1502, 1005, '0', '0', 'admin', '2026-11-18 14:00:00', 'admin', '2026-11-22 11:05:00', '演示项目：第二批股权穿透复核（本地库直接回放）');
